	const value = {};
	const errors = {};
	const has = (key) => key in input && input[key] !== undefined;
	for (const key of [
		"title",
		"content",
		"excerpt"
	]) {
		if (has(key)) {
			if (isString(input[key])) {
				value[key] = key === "content" ? input[key] : input[key].trim();
			} else {
				errors[key] = "Must be text";
			}
		} else if (!partial) {
			value[key] = "";
		}
	}
